-- ── NEW_VISA / LEAD

UPDATE "ServiceStatus" SET "systemEvent" = NULL WHERE "serviceType" = 'NEW_VISA' AND "scope" = 'LEAD';

UPDATE "ServiceStatus" SET "name" = 'New'
WHERE "id" = (
  SELECT "id" FROM "ServiceStatus" WHERE "serviceType" = 'NEW_VISA' AND "scope" = 'LEAD' AND "name" IN ('Contacted', 'Customer Responded', 'Qualified', 'Quotation Created', 'Quotation Accepted', 'Payment Pending')
  ORDER BY array_position(ARRAY['Contacted', 'Customer Responded', 'Qualified', 'Quotation Created', 'Quotation Accepted', 'Payment Pending']::text[], "name") LIMIT 1
) AND NOT EXISTS (SELECT 1 FROM "ServiceStatus" WHERE "serviceType" = 'NEW_VISA' AND "scope" = 'LEAD' AND "name" = 'New');

INSERT INTO "ServiceStatus" ("id", "serviceType", "scope", "name", "displayOrder", "isTerminal", "blocksRefund", "customerLabel", "mapsToLeadStatus", "mapsToBookingStatus", "notificationEvent", "systemEvent", "active", "createdAt", "updatedAt")
VALUES ('ss_' || md5('NEW_VISA/LEAD/' || 'New'), 'NEW_VISA', 'LEAD', 'New', 0, false, false, 'Payment Pending', 'NEW', NULL, 'NV_COUNTRY_REQUEST_PAYMENT_PENDING', NULL, true, now(), now())
ON CONFLICT ("serviceType", "scope", "name") DO UPDATE SET
  "displayOrder" = EXCLUDED."displayOrder", "isTerminal" = EXCLUDED."isTerminal", "blocksRefund" = EXCLUDED."blocksRefund",
  "customerLabel" = EXCLUDED."customerLabel", "mapsToLeadStatus" = EXCLUDED."mapsToLeadStatus", "mapsToBookingStatus" = EXCLUDED."mapsToBookingStatus",
  "notificationEvent" = EXCLUDED."notificationEvent", "systemEvent" = EXCLUDED."systemEvent", "active" = true, "updatedAt" = now();

