WHERE "serviceStatusId" IN (SELECT "id" FROM "ServiceStatus" WHERE "serviceType" = 'NEW_VISA' AND "scope" = 'LEAD' AND "name" IN ('Contacted', 'Customer Responded', 'Qualified', 'Quotation Created', 'Quotation Accepted', 'Payment Pending'));

