INSERT INTO "ServiceStatusTransition" ("id", "fromStatusId", "toStatusId")
SELECT 'sst_' || md5(f."id" || '>' || t."id"), f."id", t."id"
FROM (VALUES
  ('New', 'User Not Responding'),
  ('New', 'Paid'),
  ('New', 'Cancelled'),
  ('New', 'On Hold'),
  ('User Not Responding', 'Paid'),
  ('User Not Responding', 'Cancelled'),
  ('User Not Responding', 'On Hold'),
  ('On Hold', 'New'),
  ('On Hold', 'User Not Responding')
) AS p("fromName", "toName")
JOIN "ServiceStatus" f ON f."serviceType" = 'NEW_VISA' AND f."scope" = 'LEAD' AND f."name" = p."fromName"
JOIN "ServiceStatus" t ON t."serviceType" = 'NEW_VISA' AND t."scope" = 'LEAD' AND t."name" = p."toName"
ON CONFLICT ("fromStatusId", "toStatusId") DO NOTHING;

