) AS p("fromName", "toName")
JOIN "ServiceStatus" f ON f."serviceType" = 'NEW_VISA' AND f."scope" = 'BOOKING' AND f."name" = p."fromName"
JOIN "ServiceStatus" t ON t."serviceType" = 'NEW_VISA' AND t."scope" = 'BOOKING' AND t."name" = p."toName"
