-- ── VISA_EXTENSION / LEAD

UPDATE "ServiceStatus" SET "systemEvent" = NULL WHERE "serviceType" = 'VISA_EXTENSION' AND "scope" = 'LEAD';

UPDATE "ServiceStatus" SET "name" = 'New'
WHERE "id" = (
  SELECT "id" FROM "ServiceStatus" WHERE "serviceType" = 'VISA_EXTENSION' AND "scope" = 'LEAD' AND "name" IN ('Follow-up Required', 'Customer Responded')
  ORDER BY array_position(ARRAY['Follow-up Required', 'Customer Responded']::text[], "name") LIMIT 1
) AND NOT EXISTS (SELECT 1 FROM "ServiceStatus" WHERE "serviceType" = 'VISA_EXTENSION' AND "scope" = 'LEAD' AND "name" = 'New');

