VALUES ('ss_' || md5('VISA_EXTENSION/LEAD/' || 'New'), 'VISA_EXTENSION', 'LEAD', 'New', 0, false, false, 'New Extension Request', 'NEW', NULL, 'EXT_01', NULL, true, now(), now())
