INSERT INTO "ServiceStatusTransition" ("id", "fromStatusId", "toStatusId")
SELECT 'sst_' || md5(f."id" || '>' || t."id"), f."id", t."id"
FROM (VALUES
  ('New', 'Eligibility Review'),
  ('New', 'Not Eligible'),
  ('New', 'Quotation Sent'),
  ('New', 'Quotation Approved'),
  ('New', 'Payment Pending'),
  ('New', 'Paid'),
  ('New', 'Cancelled'),
  ('New', 'On Hold'),
  ('Eligibility Review', 'Not Eligible'),
  ('Eligibility Review', 'Quotation Sent'),
  ('Eligibility Review', 'Quotation Approved'),
  ('Eligibility Review', 'Payment Pending'),
  ('Eligibility Review', 'Paid'),
  ('Eligibility Review', 'Cancelled'),
  ('Eligibility Review', 'On Hold'),
  ('Quotation Sent', 'Quotation Approved'),
  ('Quotation Sent', 'Payment Pending'),
  ('Quotation Sent', 'Paid'),
  ('Quotation Sent', 'Cancelled'),
  ('Quotation Sent', 'On Hold'),
  ('Quotation Approved', 'Payment Pending'),
  ('Quotation Approved', 'Paid'),
  ('Quotation Approved', 'Cancelled'),
  ('Quotation Approved', 'On Hold'),
  ('Payment Pending', 'Paid'),
  ('Payment Pending', 'Cancelled'),
  ('Payment Pending', 'On Hold'),
  ('On Hold', 'New'),
  ('On Hold', 'Eligibility Review'),
  ('On Hold', 'Quotation Sent'),
  ('On Hold', 'Quotation Approved'),
  ('On Hold', 'Payment Pending')
) AS p("fromName", "toName")
JOIN "ServiceStatus" f ON f."serviceType" = 'VISA_EXTENSION' AND f."scope" = 'LEAD' AND f."name" = p."fromName"
JOIN "ServiceStatus" t ON t."serviceType" = 'VISA_EXTENSION' AND t."scope" = 'LEAD' AND t."name" = p."toName"
ON CONFLICT ("fromStatusId", "toStatusId") DO NOTHING;

