WHERE "serviceStatusId" IN (SELECT "id" FROM "ServiceStatus" WHERE "serviceType" = 'OTB' AND "scope" = 'LEAD' AND "name" IN ('Contacted', 'Follow-up Required', 'Customer Responded', 'Qualified', 'Quotation Created', 'Quotation Accepted', 'Payment Pending'));

UPDATE "ServiceStatus" SET "name" = 'Paid'
WHERE "id" = (
  SELECT "id" FROM "ServiceStatus" WHERE "serviceType" = 'OTB' AND "scope" = 'LEAD' AND "name" IN ('Converted')
  ORDER BY array_position(ARRAY['Converted']::text[], "name") LIMIT 1
) AND NOT EXISTS (SELECT 1 FROM "ServiceStatus" WHERE "serviceType" = 'OTB' AND "scope" = 'LEAD' AND "name" = 'Paid');

