INSERT INTO "ServiceStatusTransition" ("id", "fromStatusId", "toStatusId")
SELECT 'sst_' || md5(f."id" || '>' || t."id"), f."id", t."id"
FROM (VALUES
  ('New', 'Paid'),
  ('New', 'Cancelled'),
  ('New', 'On Hold'),
  ('On Hold', 'New')
) AS p("fromName", "toName")
JOIN "ServiceStatus" f ON f."serviceType" = 'OTB' AND f."scope" = 'LEAD' AND f."name" = p."fromName"
JOIN "ServiceStatus" t ON t."serviceType" = 'OTB' AND t."scope" = 'LEAD' AND t."name" = p."toName"
ON CONFLICT ("fromStatusId", "toStatusId") DO NOTHING;

