ON CONFLICT ("fromStatusId", "toStatusId") DO NOTHING;

-- ── RETURN_TICKET / LEAD

UPDATE "ServiceStatus" SET "systemEvent" = NULL WHERE "serviceType" = 'RETURN_TICKET' AND "scope" = 'LEAD';

UPDATE "ServiceStatus" SET "name" = 'New'
WHERE "id" = (
  SELECT "id" FROM "ServiceStatus" WHERE "serviceType" = 'RETURN_TICKET' AND "scope" = 'LEAD' AND "name" IN ('Contacted', 'Follow-up Required', 'Customer Responded', 'Qualified', 'Quotation Created', 'Quotation Accepted', 'Payment Pending')
  ORDER BY array_position(ARRAY['Contacted', 'Follow-up Required', 'Customer Responded', 'Qualified', 'Quotation Created', 'Quotation Accepted', 'Payment Pending']::text[], "name") LIMIT 1
) AND NOT EXISTS (SELECT 1 FROM "ServiceStatus" WHERE "serviceType" = 'RETURN_TICKET' AND "scope" = 'LEAD' AND "name" = 'New');

INSERT INTO "ServiceStatus" ("id", "serviceType", "scope", "name", "displayOrder", "isTerminal", "blocksRefund", "customerLabel", "mapsToLeadStatus", "mapsToBookingStatus", "notificationEvent", "systemEvent", "active", "createdAt", "updatedAt")
VALUES ('ss_' || md5('RETURN_TICKET/LEAD/' || 'New'), 'RETURN_TICKET', 'LEAD', 'New', 0, false, false, 'New Request Received', 'NEW', NULL, 'RVT_NEW', NULL, true, now(), now())
ON CONFLICT ("serviceType", "scope", "name") DO UPDATE SET
  "displayOrder" = EXCLUDED."displayOrder", "isTerminal" = EXCLUDED."isTerminal", "blocksRefund" = EXCLUDED."blocksRefund",
  "customerLabel" = EXCLUDED."customerLabel", "mapsToLeadStatus" = EXCLUDED."mapsToLeadStatus", "mapsToBookingStatus" = EXCLUDED."mapsToBookingStatus",
  "notificationEvent" = EXCLUDED."notificationEvent", "systemEvent" = EXCLUDED."systemEvent", "active" = true, "updatedAt" = now();

UPDATE "Lead" SET "serviceStatusId" = (SELECT "id" FROM "ServiceStatus" WHERE "serviceType" = 'RETURN_TICKET' AND "scope" = 'LEAD' AND "name" = 'New'), "status" = 'NEW'
WHERE "serviceStatusId" IN (SELECT "id" FROM "ServiceStatus" WHERE "serviceType" = 'RETURN_TICKET' AND "scope" = 'LEAD' AND "name" IN ('Contacted', 'Follow-up Required', 'Customer Responded', 'Qualified', 'Quotation Created', 'Quotation Accepted', 'Payment Pending'));

UPDATE "ServiceStatus" SET "name" = 'Paid'
WHERE "id" = (
  SELECT "id" FROM "ServiceStatus" WHERE "serviceType" = 'RETURN_TICKET' AND "scope" = 'LEAD' AND "name" IN ('Converted')
