  ('New Quote Requested', 'Payment Pending'),
  ('New Quote Requested', 'Paid'),
  ('New Quote Requested', 'Cancelled'),
  ('New Quote Requested', 'On Hold'),
  ('Quotation Approved', 'Payment Pending'),
  ('Quotation Approved', 'Paid'),
  ('Quotation Approved', 'Cancelled'),
  ('Quotation Approved', 'On Hold'),
  ('Payment Pending', 'Paid'),
  ('Payment Pending', 'Cancelled'),
  ('Payment Pending', 'On Hold'),
  ('On Hold', 'New'),
  ('On Hold', 'Quotation Sent'),
  ('On Hold', 'Expiring'),
  ('On Hold', 'Expired'),
  ('On Hold', 'New Quote Requested'),
  ('On Hold', 'Quotation Approved'),
  ('On Hold', 'Payment Pending')
) AS p("fromName", "toName")
JOIN "ServiceStatus" f ON f."serviceType" = 'FLIGHT_SPECIAL_FARE' AND f."scope" = 'LEAD' AND f."name" = p."fromName"
JOIN "ServiceStatus" t ON t."serviceType" = 'FLIGHT_SPECIAL_FARE' AND t."scope" = 'LEAD' AND t."name" = p."toName"
ON CONFLICT ("fromStatusId", "toStatusId") DO NOTHING;

