UPDATE "ServiceStatus" SET "systemEvent" = NULL WHERE "serviceType" = 'FLIGHT_SPECIAL_FARE' AND "scope" = 'BOOKING';

UPDATE "ServiceStatus" SET "name" = 'Payment Pending'
WHERE "id" = (
  SELECT "id" FROM "ServiceStatus" WHERE "serviceType" = 'FLIGHT_SPECIAL_FARE' AND "scope" = 'BOOKING' AND "name" IN ('New', 'Availability Pending', 'Quote Sent', 'Quote Viewed', 'Expiring', 'New Quote Requested', 'Follow-up Due', 'Expired')
  ORDER BY array_position(ARRAY['New', 'Availability Pending', 'Quote Sent', 'Quote Viewed', 'Expiring', 'New Quote Requested', 'Follow-up Due', 'Expired']::text[], "name") LIMIT 1
) AND NOT EXISTS (SELECT 1 FROM "ServiceStatus" WHERE "serviceType" = 'FLIGHT_SPECIAL_FARE' AND "scope" = 'BOOKING' AND "name" = 'Payment Pending');

