  "notificationEvent" = EXCLUDED."notificationEvent", "systemEvent" = EXCLUDED."systemEvent", "active" = true, "updatedAt" = now();

INSERT INTO "ServiceStatus" ("id", "serviceType", "scope", "name", "displayOrder", "isTerminal", "blocksRefund", "customerLabel", "mapsToLeadStatus", "mapsToBookingStatus", "notificationEvent", "systemEvent", "active", "createdAt", "updatedAt")
VALUES ('ss_' || md5('FLIGHT_SPECIAL_FARE/BOOKING/' || 'Cancelled and Refunded'), 'FLIGHT_SPECIAL_FARE', 'BOOKING', 'Cancelled and Refunded', 210, true, false, 'Booking Cancelled — Refund Completed', NULL, 'REFUNDED', NULL, 'CANCELLED_AND_REFUNDED', true, now(), now())
ON CONFLICT ("serviceType", "scope", "name") DO UPDATE SET
  "displayOrder" = EXCLUDED."displayOrder", "isTerminal" = EXCLUDED."isTerminal", "blocksRefund" = EXCLUDED."blocksRefund",
  "customerLabel" = EXCLUDED."customerLabel", "mapsToLeadStatus" = EXCLUDED."mapsToLeadStatus", "mapsToBookingStatus" = EXCLUDED."mapsToBookingStatus",
  "notificationEvent" = EXCLUDED."notificationEvent", "systemEvent" = EXCLUDED."systemEvent", "active" = true, "updatedAt" = now();

UPDATE "ServiceStatus" SET "active" = false, "systemEvent" = NULL, "notificationEvent" = NULL WHERE "serviceType" = 'FLIGHT_SPECIAL_FARE' AND "scope" = 'BOOKING' AND "name" NOT IN ('Payment Pending', 'Paid', 'Final Confirmation', 'Documents Pending', 'Documents Validated', 'Seat Unavailable', 'Alternative Offered', 'Additional Payment Pending', 'Sent to Airlines', 'Ticket Issued', 'Booking On Hold', 'Cancellation Requested', 'Ticket Cancellation Requested', 'Sent to Airlines for Cancellation', 'Cancellation Quotation Sent', 'Cancellation Quotation Approved', 'Cancellation Rejected', 'Ticket Cancelled', 'Refund Pending', 'Refund Processing', 'Refund Completed', 'Cancelled and Refunded');

