INSERT INTO "NotificationTemplate" ("id", "event", "channel", "subject", "body", "active", "heading", "ctaLabel", "ctaLink", "createdAt", "updatedAt")
VALUES ('nt_' || md5('VC_VISA_APPROVED_PARTIAL_APPLICANTS/EMAIL'), 'VC_VISA_APPROVED_PARTIAL_APPLICANTS', 'EMAIL', 'Partial visa approval — {{booking_id}}', 'Hi {{customer_name}},

