INSERT INTO "NotificationTemplate" ("id", "event", "channel", "subject", "body", "active", "heading", "ctaLabel", "ctaLink", "createdAt", "updatedAt")
VALUES ('nt_' || md5('RVT_TICKET_ISSUED/EMAIL'), 'RVT_TICKET_ISSUED', 'EMAIL', 'Ticket Issued — {{booking_id}}', 'Dear {{customer_name}},

Your Return Verified Ticket reservation for request {{booking_id}} has been issued.
Passenger(s): {{passenger_names}}
Travel date: {{travel_date}}

Your ticket/reservation PDF is attached.
Please check the details carefully. Acceptance is subject to the relevant airline and authority requirements.

⚠️ Important: Please Verify Your Details
Kindly check your name, travel dates, route, and all reservation details carefully. If you notice any errors, inform us within 4 hours of receiving this message. After this period a new ticket is required at an additional cost.

Disclaimer:
• A return ticket or reservation does not guarantee boarding, visa approval, immigration clearance, or entry into any country.
• Final decisions regarding boarding and entry rest with the airline and relevant immigration authorities.
• Please ensure you meet all visa, passport, and travel requirements before departure.

We recommend verifying all details promptly to avoid last-minute issues.
Have a safe and pleasant journey with TripNexio!', true, NULL, 'Download Ticket', 'ticket_download_link', now(), now())
ON CONFLICT ("event", "channel") DO NOTHING;

