INSERT INTO "NotificationTemplate" ("id", "event", "channel", "subject", "body", "active", "heading", "ctaLabel", "ctaLink", "createdAt", "updatedAt")
VALUES ('nt_' || md5('SF_15/EMAIL'), 'SF_15', 'EMAIL', 'Your flight ticket is issued — {{booking_id}}', 'Hi {{customer_name}},

Your ticket for {{booking_id}} has been issued.
Passenger(s): {{passenger_names}}
Route: {{origin}} → {{destination}} | Date: {{travel_date}}
Flight: {{airline_flight_number}}
Check all details immediately and report errors within 12 hours of ticket issuance.

Airport Reporting: Arrive at least 2 hours before domestic flights and 4 hours before international flights.
1. Travel Documents: Carry a valid government-issued photo ID for domestic travel. International travellers must carry a valid passport, applicable visas and transit documents.
2. Terminal & Timings: Confirm the departure terminal and latest flight status with the airline. All timings are local to the respective airports.
3. Web Check-in: Complete airline web check-in and obtain your boarding pass where required.
4. Baggage: Check the baggage allowance mentioned on your ticket.
5. Changes & Refunds: Cancellations, refunds and rescheduling are subject to airline fare rules and applicable charges.
6. Travel Requirements: Passengers are responsible for meeting visa, transit, immigration and OTB requirements, where applicable.
7. Ticket Verification Disclaimer: Please check all ticket details, including passenger names, travel dates, flight timings and routes, immediately upon receipt. Report any errors to TripNexio within 12 hours of ticket issuance. Later corrections will be subject to airline rules, availability and applicable charges.

Have a safe and pleasant journey with TripNexio!', true, NULL, 'Download Ticket', 'ticket_download_link', now(), now())
ON CONFLICT ("event", "channel") DO NOTHING;

